const msg = $input.first().json.message;
const chatId = msg.chat.id;
const text = msg.text || msg.caption || '';
const hasPhoto = !!(msg.photo && msg.photo.length > 0);
let fileId = '';
if (hasPhoto) {
  fileId = msg.photo[msg.photo.length - 1].file_id;
}
return [{
  json: {
    chatId,
    text,
    hasPhoto,
    fileId,
    messageType: hasPhoto ? (text ? 'photo_with_text' : 'photo_only') : 'text_only'
  }
}];

const binaryData = $input.first().binary;
const binaryKey = Object.keys(binaryData)[0];
const imageBuffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const base64Image = imageBuffer.toString('base64');
let mimeType = binaryData[binaryKey].mimeType || 'image/jpeg';
if (!mimeType.startsWith('image/')) {
  mimeType = 'image/jpeg';
}
const captionText = $('Classify Telegram Message Content').item.json.text;

let userPrompt = 'Extract all contact information from this image (business card, screenshot, etc).';
if (captionText) {
  userPrompt += '\n\nThe user also included this note: "' + captionText + '"';
}

const systemPrompt = `You are a contact information extractor. Given an image (business card, screenshot, etc) and optionally accompanying text, extract contact details into structured JSON.

Always return a JSON ARRAY of contact objects, even for a single contact:
[
  {
    "action": "create" or "update" or "lookup",
    "name": {
      "givenName": "first name",
      "familyName": "last name or empty string"
    },
    "email": "email or empty string",
    "phone": "phone number or empty string",
    "company": "company name or empty string",
    "jobTitle": "job title or empty string",
    "notes": "any additional notes or empty string"
  }
]

Rules:
- If the image contains multiple contacts or business cards, return one object per contact
- If the user is asking to find, look up, search for, or retrieve info about a contact, set action to "lookup"
- If the user provides contact details without explicitly asking to search, default action to "create"
- If the text says "update" or implies changing existing info, set action to "update"
- Extract ALL available fields from the image and text
- Phone numbers should include country code if visible
- If only a single name is given with no clear first/last split, put it all in givenName
- If the image does not contain contact information, return [{"action": "ignore"}]
- Return ONLY the JSON array, no markdown, no backticks, no explanation`;

const requestBody = {
  model: 'gpt-4o-mini',
  max_tokens: 2000,
  messages: [
    { role: 'system', content: systemPrompt },
    {
      role: 'user',
      content: [
        {
          type: 'image_url',
          image_url: { url: 'data:' + mimeType + ';base64,' + base64Image }
        },
        { type: 'text', text: userPrompt }
      ]
    }
  ]
};

return [{
  json: {
    requestBody,
    chatId: $('Classify Telegram Message Content').item.json.chatId
  }
}];

const response = $input.first().json;
const aiText = response.choices[0].message.content;
const chatId = $('Classify Telegram Message Content').item.json.chatId;

let parsed;
try {
  let cleaned = aiText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  return [{
    json: {
      error: true,
      action: 'error',
      message: 'Failed to parse vision response: ' + e.message,
      chatId
    }
  }];
}

// Handle both single object and array responses
let contacts = Array.isArray(parsed) ? parsed : [parsed];

return contacts.map(c => {
  c.chatId = chatId;
  c.error = false;

  if (c.action !== 'ignore') {
    // Search by identifiers that ALREADY exist on the contact.
    // Phone is last: on an update the phone is usually the NEW value being
    // added, so searching by it guarantees a miss and creates a duplicate.
    const fullName = (c.name && c.name.givenName)
      ? (c.name.givenName + ' ' + (c.name.familyName || '')).trim()
      : '';
    let searchQuery = '';
    if (c.email) {
      searchQuery = c.email;
    } else if (fullName) {
      searchQuery = fullName;
    } else if (c.phone) {
      searchQuery = c.phone;
    }
    c.searchQuery = searchQuery;
  }

  return { json: c };
});

const text = $('Classify Telegram Message Content').item.json.text;
const chatId = $('Classify Telegram Message Content').item.json.chatId;

const systemPrompt = `You are a contact information classifier and extractor.

First, determine if this message is a request to create, update, or look up a contact. Messages about contacts typically mention a person's name along with details like email, phone number, company, job title, or explicitly say things like "add contact", "save contact", "update contact", "new contact", "find contact", "look up", "search for", "do I have", "what's their email", "look for", etc.

If the message is NOT about creating, updating, or looking up a contact, return ONLY:
[{"action": "ignore"}]

If the message IS about contacts, extract the details and return a JSON ARRAY of contact objects. Always return an array, even for a single contact:
[
  {
    "action": "create" or "update" or "lookup",
    "name": {
      "givenName": "first name",
      "familyName": "last name or empty string"
    },
    "email": "email or empty string",
    "phone": "phone number or empty string",
    "company": "company name or empty string",
    "jobTitle": "job title or empty string",
    "notes": "any additional notes or empty string"
  }
]

Rules:
- If the message contains multiple contacts, return one object per contact in the array
- If the user is asking to find, look up, search for, or retrieve info about a contact, set action to "lookup"
- If the user provides contact details (name with email, phone, company, etc.) without explicitly asking to search or look up, ALWAYS default action to "create"
- Words like "add", "save", "new", or simply providing contact info = "create"
- Only use "lookup" when the user is clearly asking a question about an existing contact
- If the text says "update" or implies changing existing info, set action to "update"
- Extract ALL available fields from the text
- Phone numbers should include country code if provided
- If only a single name is given with no clear first/last split, put it all in givenName
- Return ONLY the JSON array, no markdown, no backticks, no explanation`;

const requestBody = {
  model: 'gpt-4o-mini',
  max_tokens: 2000,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: text }
  ]
};

return [{ json: { requestBody, chatId } }];

const response = $input.first().json;
const aiText = response.choices[0].message.content;
const chatId = $('Classify Telegram Message Content').item.json.chatId;

let parsed;
