  if (c.action !== 'ignore') {
    // Search by identifiers that ALREADY exist on the contact.
    // Phone is last: on an update the phone is usually the NEW value being
    // added, so searching by it guarantees a miss and creates a duplicate.
    const fullName = (c.name && c.name.givenName)
      ? (c.name.givenName + ' ' + (c.name.familyName || '')).trim()
      : '';
    let searchQuery = '';
    if (c.email) {
      searchQuery = c.email;
    } else if (fullName) {
      searchQuery = fullName;
    } else if (c.phone) {
      searchQuery = c.phone;
    }
    c.searchQuery = searchQuery;
  }

  return { json: c };
