const contact = $('Check If Contact Action Required').item.json;
const results = $('Fetch Google Contacts').item.json.results || [];

if (!results.length) {
  return [{ json: {
    message: '🔍 No contacts found matching "' + contact.searchQuery + '"',
    chatId: contact.chatId
  }}];
}

const parts = ['🔍 Found ' + results.length + ' contact(s):'];
for (const r of results) {
  const p = r.person;
  const name = p.names && p.names[0] ? p.names[0].displayName : 'Unknown';
  const email = p.emailAddresses && p.emailAddresses[0] ? p.emailAddresses[0].value : '';
  const phone = p.phoneNumbers && p.phoneNumbers[0] ? p.phoneNumbers[0].value : '';
  const org = p.organizations && p.organizations[0] ? p.organizations[0].name : '';
  const title = p.organizations && p.organizations[0] ? p.organizations[0].title : '';

  let line = '\n👤 ' + name;
  if (email) line += '\n   📧 ' + email;
  if (phone) line += '\n   📱 ' + phone;
  if (org) line += '\n   🏢 ' + org;
  if (title) line += '\n   💼 ' + title;
  parts.push(line);
}

return [{ json: {
  message: parts.join('\n'),
  chatId: contact.chatId
}}];

const contact = $('Check If Contact Action Required').item.json;
const results = $('Check If Contact Exists').item.json.results || [];

// Never blind-pick results[0]: a name-only search can return several people
// and we would silently overwrite the wrong contact.
const digits = s => String(s || '').replace(/\D/g, '');
const wantEmail = (contact.email || '').toLowerCase();
const wantName = ((contact.name && contact.name.givenName || '') + ' ' +
                  (contact.name && contact.name.familyName || '')).trim().toLowerCase();

function score(person) {
  let s = 0;
  if (wantEmail && (person.emailAddresses || [])
      .some(e => (e.value || '').toLowerCase() === wantEmail)) s += 100;
  if (contact.phone && (person.phoneNumbers || [])
      .some(p => digits(p.value) === digits(contact.phone))) s += 50;
  const display = ((person.names && person.names[0] && person.names[0].displayName) || '')
      .trim().toLowerCase();
  if (wantName && display === wantName) s += 25;
  else if (wantName && display.startsWith(wantName)) s += 5;
  return s;
}

const ranked = results
  .map(r => ({ person: r.person, s: score(r.person) }))
  .sort((a, b) => b.s - a.s);

if (!ranked.length) {
  throw new Error('No contact to update — search returned nothing.');
}
// Ambiguous: several candidates and none matched on a real identifier.
if (ranked.length > 1 && ranked[0].s === 0) {
  const who = ranked
    .map(r => (r.person.names && r.person.names[0] && r.person.names[0].displayName) || '?')
    .join(', ');
  throw new Error('Ambiguous match for "' + (contact.searchQuery || wantName) +
    '" (' + ranked.length + ' candidates: ' + who + '). Refine with an email address.');
}
// A tie on the top score is also ambiguous.
if (ranked.length > 1 && ranked[1].s === ranked[0].s) {
  throw new Error('Two contacts matched "' + (contact.searchQuery || wantName) +
    '" equally well. Refine with an email address.');
}

const existing = ranked[0].person;

// Google's PATCH replaces every field listed in updatePersonFields wholesale,
// so anything we don't send back is destroyed. Merge, don't overwrite.

const body = { etag: existing.etag };

// --- Names: keep existing parts when the message didn't supply them ---
const exName = (existing.names && existing.names[0]) || {};
const newGiven = (contact.name && contact.name.givenName) || '';
const newFamily = (contact.name && contact.name.familyName) || '';
body.names = [{
  givenName: newGiven || exName.givenName || '',
  familyName: newFamily || exName.familyName || ''
}];

// --- Emails: append if new, case-insensitive dedupe ---
const exEmails = existing.emailAddresses || [];
if (contact.email) {
  const seen = exEmails.some(e => (e.value || '').toLowerCase() === contact.email.toLowerCase());
  body.emailAddresses = seen ? exEmails : [...exEmails, { value: contact.email }];
} else if (exEmails.length) {
  body.emailAddresses = exEmails;
}

// --- Phones: append if new, compare digits only so formatting doesn't fool it ---
const exPhones = existing.phoneNumbers || [];
if (contact.phone) {
  const seen = exPhones.some(p => digits(p.value) === digits(contact.phone));
  body.phoneNumbers = seen ? exPhones : [...exPhones, { value: contact.phone }];
} else if (exPhones.length) {
  body.phoneNumbers = exPhones;
}

// --- Organization: fill blanks from the existing record ---
const exOrg = (existing.organizations && existing.organizations[0]) || {};
if (contact.company || contact.jobTitle) {
  body.organizations = [{
    name: contact.company || exOrg.name || '',
    title: contact.jobTitle || exOrg.title || ''
  }];
} else if (existing.organizations && existing.organizations.length) {
  body.organizations = existing.organizations;
}

// --- Notes: append to the existing biography rather than clobbering it ---
const today = new Date().toISOString().split('T')[0];
const exBio = (existing.biographies && existing.biographies[0] && existing.biographies[0].value) || '';

const additions = ['Updated: ' + today];
if (contact.notes) additions.push(contact.notes);
const appended = additions.join('\n');

body.biographies = [{
  value: exBio ? exBio.trimEnd() + '\n\n' + appended : appended,
  contentType: 'TEXT_PLAIN'
}];

return [{ json: { body, resourceName: existing.resourceName, chatId: contact.chatId, contact } }];

const contact = $('Check If Contact Action Required').item.json;

const body = {
  names: [{ givenName: contact.name && contact.name.givenName || '', familyName: contact.name && contact.name.familyName || '' }]
};

if (contact.email) {
  body.emailAddresses = [{ value: contact.email }];
}
if (contact.phone) {
  body.phoneNumbers = [{ value: contact.phone }];
}
if (contact.company || contact.jobTitle) {
  body.organizations = [{ name: contact.company || '', title: contact.jobTitle || '' }];
}

// Always add date and any notes
const today = new Date().toISOString().split('T')[0];
let notesText = 'Added: ' + today;
if (contact.notes) {
  notesText += '\n' + contact.notes;
}
body.biographies = [{ value: notesText, contentType: 'TEXT_PLAIN' }];

return [{ json: { body, chatId: contact.chatId, contact } }];

const contact = $('Check If Contact Action Required').item.json;
const inputNode = $input.first().json;

// Check the original action from the AI classification
const action = contact.action === 'update' ? 'updated' : 'created';

const name = ((contact.name && contact.name.givenName || '') + ' ' + (contact.name && contact.name.familyName || '')).trim();

const parts = ['✅ Contact ' + action + ': ' + name];
if (contact.email) parts.push('📧 ' + contact.email);
if (contact.phone) parts.push('📱 ' + contact.phone);
if (contact.company) parts.push('🏢 ' + contact.company);
if (contact.jobTitle) parts.push('💼 ' + contact.jobTitle);

return [{ json: { message: parts.join('\n'), chatId: contact.chatId } }];
